import { Group, PlaneGeometry, AmbientLight, DirectionalLight, Matrix4, Vector3, Quaternion, Color, MeshStandardNodeMaterial, MeshBasicNodeMaterial, SphereGeometry, IcosahedronGeometry, InstancedMesh } from 'three/webgpu';
import { mix, uv, color, position, neg, div, clamp } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group: THGroup, PlaneGeometry: THPlaneGeometry, AmbientLight: THAmbientLight, DirectionalLight: THDirectionalLight, Matrix4: THMatrix4, Vector3: THVector3, Quaternion: THQuaternion } = ctx.THREE;

  // Root group (adapter applies position/rotation/scale)
  const root = new THGroup();

  // ---------- Backdrop Gradient Plane ----------
  const backdropGeom = new THPlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  // vertical gradient: top #0b0b10, bottom #16161d
  backdropMat.colorNode = mix(color('#0b0b10'), color('#16161d'), uv().y);
  backdropMat.transparent = true;
  backdropMat.depthWrite = false;
  const backdrop = new ctx.THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Core Particle Sphere ----------
  const coreCount = 90;
  const coreGeom = new IcosahedronGeometry(0.012, 0);
  const coreMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 1,
    transparent: true,
    blending: ctx.THREE.AdditiveBlending,
    depthWrite: false,
  });
  const coreMesh = new InstancedMesh(coreGeom, coreMat, coreCount);
  const coreMatrix = new THMatrix4();
  const corePos = new THVector3();
  const coreQuat = new THQuaternion();
  for (let i = 0; i < coreCount; i++) {
    // random point inside sphere radius 0.5
    const phi = Math.acos(2 * Math.random() - 1);
    const theta = 2 * Math.PI * Math.random();
    const r = Math.cbrt(Math.random()) * 0.5;
    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.sin(phi) * Math.sin(theta);
    const z = r * Math.cos(phi);
    corePos.set(x, y, z);
    coreMatrix.compose(corePos, coreQuat, new THVector3(1, 1, 1));
    coreMesh.setMatrixAt(i, coreMatrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  root.add(coreMesh);

  // ---------- Instanced Particle Field ----------
  const particleCount = 1200;
  const particleGeom = new IcosahedronGeometry(0.012, 0);
  const particleMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacityNode: mix(
      0.9,
      0.15,
      clamp(div(neg(position().z), 5), 0, 1)
    ),
  });
  const particles = new InstancedMesh(particleGeom, particleMat, particleCount);
  const dummyMatrix = new THMatrix4();
  const dummyPos = new THVector3();
  const dummyQuat = new THQuaternion();
  const coreCenter = new THVector3(0, 0, -1.5);
  const radii = new THVector3(3, 2, 2.5); // half extents of 6x4x5 ellipsoid
  for (let i = 0; i < particleCount; i++) {
    // random point on ellipsoidal shell
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    const x = radii.x * Math.sin(phi) * Math.cos(theta);
    const y = radii.y * Math.sin(phi) * Math.sin(theta);
    const z = radii.z * Math.cos(phi);
    dummyPos.set(x, y, z).add(coreCenter);
    dummyMatrix.compose(dummyPos, dummyQuat, new THVector3(1, 1, 1));
    particles.setMatrixAt(i, dummyMatrix);
  }
  particles.instanceMatrix.needsUpdate = true;
  root.add(particles);

  // ---------- Text Elements ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 124,
      color: (config.intent?.visualSpec?.colors?.ink) ?? '#16161d',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    if (item.role === 'hero') {
      txt.position.set(0, 0.5, 0.5);
    } else if (item.role === 'subhead') {
      txt.position.set(0, -0.25, 0.5);
    } else if (item.role === 'caption') {
      txt.position.set(0, -2.25, 0.5);
    }
    root.add(txt);
  }

  // ---------- Lighting ----------
  const ambient = new THAmbientLight(0xffffff, 0.6);
  root.add(ambient);
  const keyLight = new THDirectionalLight(0xffffff, 1.2);
  keyLight.position.set(5, 5, 5);
  root.add(keyLight);
  const rimLight = new THDirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-5, -5, -5);
  root.add(rimLight);

  // ---------- Cinematic Primitives ----------
  const activePrimitives = [];
  const primitivesConfig = config.cinematicPrimitives || [];
  for (const prim of primitivesConfig) {
    const instance = ctx.primitives[prim.name](root, prim.params);
    activePrimitives.push(instance);
  }

  // ---------- GSAP Timelines ----------
  const timelines = [];

  // Core pulse (emissive intensity sine wave at 0.1 Hz)
  const pulseTl = gsap.to(coreMat, {
    emissiveIntensity: 1.5,
    duration: 5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut',
  });
  timelines.push(pulseTl);

  // Attach empty handlers container
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = function () {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    coreGeom.dispose();
    coreMat.dispose();
    particleGeom.dispose();
    particleMat.dispose();

    // Dispose meshes
    coreMesh.geometry.dispose();
    coreMesh.material.dispose();
    particles.geometry.dispose();
    particles.material.dispose();

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();

    // Cleanup primitives
    for (const p of activePrimitives) p.cleanup && p.cleanup();

    // Remove from parent if still attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
